-- A claimed physical object cannot gain a new reference; newer immutable versions remain independent.
CREATE TRIGGER asset_file_notices_insert BEFORE INSERT ON notices WHEN EXISTS(SELECT 1 FROM asset_file_cleanup c WHERE NEW.thumbnail_url='/r2-assets/'||c.logical_key AND NOT EXISTS(SELECT 1 FROM asset_file_references r WHERE r.logical_key=c.logical_key AND r.version_key<>c.object_key)) OR EXISTS(SELECT 1 FROM json_each(NEW.image_urls) image WHERE EXISTS(SELECT 1 FROM asset_file_cleanup c WHERE image.value='/r2-assets/'||c.logical_key AND NOT EXISTS(SELECT 1 FROM asset_file_references r WHERE r.logical_key=c.logical_key AND r.version_key<>c.object_key))) BEGIN SELECT RAISE(ABORT,'asset_file_cleanup_reference_conflict'); END;
